document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("theme-toggle"),e=document.documentElement;n&&n.addEventListener("click",()=>{const t=e.getAttribute("data-theme");t==="dark"?(e.removeAttribute("data-theme"),localStorage.setItem("theme","light")):(e.setAttribute("data-theme","dark"),localStorage.setItem("theme","dark"))});const s=document.querySelectorAll("#TableOfContents a"),t=[];s.forEach(e=>{const n=e.getAttribute("href");if(n&&n.startsWith("#")){const s=n.slice(1),e=document.getElementById(s);e&&t.push(e)}}),t.length>0&&window.addEventListener("scroll",()=>{let e="";t.forEach(t=>{const n=t.offsetTop;window.scrollY>=n-150&&(e=t.getAttribute("id"))}),s.forEach(t=>{t.classList.remove("active");const n=t.getAttribute("href");e&&n.includes(e)&&t.classList.add("active")})})})